import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [wallet, setWallet] = useState(null);
  const [showPrivateKey, setShowPrivateKey] = useState(false);
  const bark = new Audio("/bark.wav");

  // 🐶 Fetch wallet from backend
  const fetchWallet = () => {
    axios.get('http://localhost:8000/api/create_wallet')
      .then(res => {
        setWallet(res.data);
        setShowPrivateKey(false); // Reset visibility
        bark.play();              // Bark!
      })
      .catch(err => console.error("API error:", err));
  };

  useEffect(() => {
    fetchWallet(); // Fetch on first load
  }, []);

  const togglePrivateKey = () => {
    setShowPrivateKey(!showPrivateKey);
    bark.play(); // Bark on toggle
  };

  const downloadWallet = () => {
    const element = document.createElement("a");
    const file = new Blob(
      [ `Address: ${wallet.address}\nPrivate Key: ${wallet.private_key}` ],
      { type: "text/plain" }
    );
    element.href = URL.createObjectURL(file);
    element.download = "puppy_wallet.txt";
    document.body.appendChild(element);
    element.click();
    bark.play(); // Bark on download
  };

  if (!wallet) return <div className="App"><h2>🐾 Generating your Puppy Wallet...</h2></div>;

  return (
    <div className="App">
      <h1>🐶 Puppy Wallet 🐶</h1>

      {/* 🎉 Create New Wallet Button */}
      <button className="create-wallet" onClick={fetchWallet}>
         Create a New ETH Wallet
      </button>

      <p><strong>Address:</strong><br /> {wallet.address}</p>

      <img src={wallet.qr_code} alt="QR Code" width="200" />

      <div className="private-key">
        <strong>Private Key:</strong><br />
        {showPrivateKey ? wallet.private_key : '••••••••••••••••••••••••••••'}
        <br />
        <button onClick={togglePrivateKey}>
          {showPrivateKey ? "Hide 🔒" : "Reveal 🔓"}
        </button>
      </div>

      <button className="download" onClick={downloadWallet}>
        ⬇️ Download Wallet
      </button>

      {/*  Donation Footer */}
      <div className="donation" style={{ marginTop: '40px', fontSize: '14px', color: '#555' }}>
        <p>
           If you would like to support the project,<br />
          donations can be made to:<br />
          <code>0x279C0C2B6eF16d471CD4e5eC525FFDD8Eeae5446</code>
        </p>
      </div>
    </div>
  );
}

export default App;
